const BO_RULES = [[/^\+(\d+) днес$/, '+$1 today'], [/^(\d+) чакат куриер$/, '$1 awaiting courier'], [/^(\d+) поръчки с НП$/, '$1 orders with COD'], [/^(\d+) поръчки$/, '$1 orders'], [/^(\d+) върнати · (\d+) отказани$/, '$1 returned · $2 cancelled'], [/^за изплащане (.+)$/, 'to pay out $1'], [/^(\d+) дни · (\d+) поръчки$/, '$1 days · $2 orders'], [/^за (\d+) дни · (\d+) поръчки$/, 'over $1 days · $2 orders'], [/^за (\d+) дни$/, 'over $1 days'], [/^(\d+) бр\.$/, '$1 pcs'], [/^Бр\.: (.+)$/, 'Qty: $1'], [/^Добро утро, (.+)$/, 'Good morning, $1'], [/^Добър ден, (.+)$/, 'Good afternoon, $1'], [/^Добър вечер, (.+)$/, 'Good evening, $1'], [/^(.+) · по ден на доставка$/, '$1 · by delivery day'], [/^изплатено (.+)$/, 'paid out $1'], [/^предстои (.+)$/, 'coming $1'], [/^(\d+) изплащания$/, '$1 payouts'], [/^1 изплащане$/, '1 payout'], [/^1 поръчка$/, '1 order'], [/^(\d+) доставени поръчки$/, '$1 delivered orders'], [/^1 доставена поръчка$/, '1 delivered order'], [/^за (\d+) поръчки$/, 'for $1 orders'], [/^за 1 поръчка$/, 'for 1 order']];
const boLang = () => (((appsmith.model || {}).lang) === 'en' ? 'en' : 'bg');

function boPhrase(s) {
  if (BO_EN[s]) return BO_EN[s];
  for (const [re, to] of BO_RULES) { if (re.test(s)) return s.replace(re, to); }
  // "Събота, 19 септември · София" - one node, three pieces.
  const cap = (w) => (w ? w.charAt(0).toUpperCase() + w.slice(1) : w);
  const day = (w) => BO_DAYS[w] || BO_DAYS[w.toLowerCase()];
  const month = (w) => BO_MONTHS[w] || BO_MONTHS[w.toLowerCase()];
  const date = s.match(/^([А-Яа-я]+),\s*(\d+)\s+([А-Яа-я]+)(.*)$/);
  if (date && day(date[1]) && month(date[3])) {
    const tail = date[4].trim();
    return cap(day(date[1])) + ', ' + date[2] + ' ' + month(date[3]) + (tail ? ' ' + boPhrase(tail) : '');
