  const dayNum = s.match(/^([А-Яа-я]+) (\d+)$/);
  if (dayNum && day(dayNum[1])) return cap(day(dayNum[1])) + ' ' + dayNum[2];
  if (day(s)) return cap(day(s));
  if (month(s)) return cap(month(s));
